+  logRequest(req);
+  const body = req.body && typeof req.body === 'object' ? req.body : {};
+  const profile = {};
+  for (const field of WRITABLE_FIELDS) {
+    if (body[field] !== undefined) profile[field] = body[field];
+  }
+  saveProfile(profile)
     .then((saved) => enrich(saved))
